impl Solution {
    pub fn stone_game_v(stone_value: Vec<i32>) -> i32 {
        let n = stone_value.len();
        let mut prefix_sum = vec![0; n + 1];
        for i in 0..n {
            prefix_sum[i + 1] = prefix_sum[i] + stone_value[i] as i32;
        }

        let mut dp = vec![vec![0; n]; n];
        for len in 1..=n {
            for i in 0..=n - len {
                let j = i + len - 1;
                dp[i][j] = 0;
                if i == j {
                    dp[i][j] = prefix_sum[j + 1] - prefix_sum[i];
                } else {
                    dp[i][j] = (prefix_sum[j + 1] - prefix_sum[i] + 1) / 2;
                }
            }
        }

        dp[0][n - 1]
    }
}

